class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Dictionary to keep track of mentions for each user
        mentions = {i: 0 for i in range(numberOfUsers)}

        # Dictionary to store user states (online/offline)
        user_states = {i: True for i in range(numberOfUsers)}

        # Dictionary to keep track of the last seen time for each user
        last_seen_time = {i: 0 for i in range(numberOfUsers)}

        for event_type, timestamp, *args in events:
            if event_type == 'MESSAGE':
                # Split mentions into individual IDs
                ids = args[0].split()

                # Update mentions for each ID
                for id_str in ids:
                    if ':' in id_str:
                        user_id = int(id_str.split(':')[1])
                        mentions[user_id] += 1
                    elif id_str == 'ALL':
                        mentions.update({i: mentions[i] + 1 for i in range(numberOfUsers)})
                    elif id_str == 'HERE':
                        mentions.update({i: mentions[i] + 1 for i in range(numberOfUsers) if user_states[i]})

            elif event_type == 'OFFLINE':
                # Mark the user as offline
                user_id = int(args[0])
                user_states[user_id] = False

                # Set the last seen time to the current timestamp minus 60 seconds
                last_seen_time[user_id] = timestamp - 60

            else:
                raise ValueError("Invalid event type")

        return list(mentions.values())

