class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers

        # Dictionary to keep track of online users
        online_users = set(range(numberOfUsers))

        for event_type, timestamp, user_ids in events:
            if event_type == "MESSAGE":
                # Update mentions for each user
                for user_id in user_ids.split():
                    if user_id.isdigit():
                        user_id = int(user_id)
                        mentions[user_id] += 1
                    elif user_id == "HERE":
                        # Update mentions for all online users
                        mentions.update(online_users)
                    else:
                        # Handle offline user
                        if user_id in online_users:
                            online_users.remove(user_id)

            elif event_type == "OFFLINE":
                # Mark user as offline
                user_id = int(user_ids)
                online_users.discard(user_id)

        return mentions

